_aws_move_outtamyway() {
    local cur="${COMP_WORDS[COMP_CWORD]}"
    local prev="${COMP_WORDS[COMP_CWORD-1]}"

    # Find positional args (skip flags and their values)
    local service="" subcommand="" pos=0
    local i=1
    while [[ $i -lt $COMP_CWORD ]]; do
        local word="${COMP_WORDS[$i]}"
        case "$word" in
            --region|--profile|--output|--query|--endpoint-url|--color|--ca-bundle|--cli-read-timeout|--cli-connect-timeout)
                ((i++))  # skip the flag's value
                ;;
            --*)
                ;;  # standalone flag, no value to skip
            *)
                if [[ $pos -eq 0 ]]; then
                    service="$word"
                elif [[ $pos -eq 1 ]]; then
                    subcommand="$word"
                fi
                ((pos++))
                ;;
        esac
        ((i++))
    done

    # Complete flag values
    case "$prev" in
        --region)
            COMPREPLY=($(compgen -W "$_aws_momy_regions" -- "$cur"))
            return
            ;;
        --profile)
            local profiles
            profiles="$(sed -n 's/^\[profile \(.*\)\]/\1/p' ~/.aws/config 2>/dev/null)"
            COMPREPLY=($(compgen -W "$profiles" -- "$cur"))
            return
            ;;
        --output)
            COMPREPLY=($(compgen -W "json text table yaml yaml-stream" -- "$cur"))
            return
            ;;
        --color)
            COMPREPLY=($(compgen -W "on off auto" -- "$cur"))
            return
            ;;
        --endpoint-url|--query|--ca-bundle|--cli-read-timeout|--cli-connect-timeout)
            return  # no completion for free-form values
            ;;
    esac

    # Complete flags
    if [[ "$cur" == --* ]]; then
        COMPREPLY=($(compgen -W "$_aws_momy_global_opts" -- "$cur"))
        return
    fi

    # Positional completion
    if [[ $pos -eq 0 ]]; then
        # Service name
        COMPREPLY=($(compgen -W "$_aws_momy_services" -- "$cur"))
    elif [[ $pos -eq 1 ]]; then
        # Subcommand for service
        local ops="${_aws_momy_ops[$service]}"
        if [[ -n "$ops" ]]; then
            COMPREPLY=($(compgen -W "$ops" -- "$cur"))
        fi
    elif [[ $pos -eq 2 && "$subcommand" == "wait" ]]; then
        # Waiter name
        local waiters="${_aws_momy_waiters[$service]}"
        if [[ -n "$waiters" ]]; then
            COMPREPLY=($(compgen -W "$waiters" -- "$cur"))
        fi
    else
        # Fall through to file completion
        COMPREPLY=($(compgen -f -- "$cur"))
    fi
}

complete -F _aws_move_outtamyway aws
